def clamp(x, lo, hi):
    """x を [lo, hi] の範囲に収めて返す。

    x が lo より小さければ lo、hi より大きければ hi、それ以外は x をそのまま返す。
    """
    return max(lo, min(x, hi))

# 値 x を下限 lo・上限 hi の範囲内に切り詰める（両端を含む）
def clamp(x, lo, hi):
    # まず hi で上を抑え、次に lo で下を抑える
    return max(lo, min(x, hi))

def clamp(x, lo, hi):
    """x を [lo, hi] の範囲に収める。"""
    if x < lo:
        return lo  # 下限より小さい
    if x > hi:
        return hi  # 上限より大きい
    return x

def clamp(x, lo, hi):
    # x を lo 以上 hi 未満に収める（hi は含まない）
    return max(lo, min(x, hi))
